```javascript
class WatermarkRemover {
    constructor() {
        this.canvas = document.getElementById('canvas');
        this.ctx = this.canvas.getContext('2d');
        this.image = null;
        this.isDrawing = false;
        this.currentTool = 'brush';
        this.brushSize = 20;
        this.history = [];
        this.startX = 0;
        this.startY = 0;

        this.init();
    }

    init() {
        document.getElementById('imageInput').addEventListener('change', (e) => this.loadImage(e));
        document.getElementById('brushSize').addEventListener('input', (e) => this.updateBrushSize(e));
        document.getElementById('undoBtn').addEventListener('click', () => this.undo());
        document.getElementById('clearBtn').addEventListener('click', () => this.clear());
        document.getElementById('downloadBtn').addEventListener('click', () => this.download());

        document.querySelectorAll('.tool-btn').forEach(btn => {
            btn.addEventListener('click', (e) => this.selectTool(e));
        });

        this.canvas.addEventListener('mousedown', (e) => this.startDrawing(e));
        this.canvas.addEventListener('mousemove', (e) => this.draw(e));
        this.canvas.addEventListener('mouseup', () => this.stopDrawing());
        this.canvas.addEventListener('mouseout', () => this.stopDrawing());
    }

    loadImage(e) {
        const file = e.target.files[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = (event) => {
            this.image = new Image();
            this.image.onload = () => {
                this.canvas.width = this.image.width;
                this.canvas.height = this.image.height;
                this.ctx.drawImage(this.image, 0, 0);
                this.saveState();

                document.getElementById('canvasContainer').style.display = 'block';
                document.getElementById('controls').style.display = 'block';
            };
            this.image.src = event.target.result;
        };
        reader.readAsDataURL(file);
    }

    selectTool(e) {
        document.querySelectorAll('.tool-btn').forEach(btn => btn.classList.remove('active'));
        e.target.classList.add('active');
        this.currentTool = e.target.dataset.tool;
    }

    updateBrushSize(e) {
        this.brushSize = e.target.value;
        document.getElementById('sizeValue').textContent = this.brushSize;
    }

    startDrawing(e) {
        this.isDrawing = true;
        const rect = this.canvas.getBoundingClientRect();
        this.startX = e.clientX - rect.left;
        this.startY = e.clientY - rect.top;

        if (this.currentTool === 'brush' || this.currentTool === 'blur') {
            this.draw(e);
        }
    }

    draw(e) {
        if (!this.isDrawing) return;

        const rect = this.canvas.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;

        if (this.currentTool === 'brush') {
            this.applyBrush(x, y);
        } else if (this.currentTool === 'blur') {
            this.applyBlur(x, y);
        }
    }

    stopDrawing() {
        if (!this.isDrawing) return;
        this.isDrawing = false;

        if (this.currentTool === 'rect') {
            const rect = this.canvas.getBoundingClientRect();
            const endX = event.clientX - rect.left;
            const endY = event.clientY - rect.top;
            this.applyRect(this.startX, this.startY, endX, endY);
        }

        this.saveState();
    }

    applyBrush(x, y) {
        const imageData = this.ctx.getImageData(
            Math.max(0, x - this.brushSize),
            Math.max(0, y - this.brushSize),
            this.brushSize * 2,
            this.brushSize * 2
        );

        const data = imageData.data;
        let r = 0, g = 0, b = 0, count = 0;

        for (let i = 0; i < data.length; i += 4) {
            r += data[i];
            g += data[i + 1];
            b += data[i + 2];
            count++;
        }

        r = Math.floor(r / count);
        g = Math.floor(g / count);
        b = Math.floor(b / count);

        this.ctx.fillStyle = `rgb(${r}, ${g}, ${b})`;
        this.ctx.beginPath();
        this.ctx.arc(x, y, this.brushSize / 2, 0, Math.PI * 2);
        this.ctx.fill();
    }

    applyBlur(x, y) {
        const size = this.brushSize;
        const imageData = this.ctx.getImageData(
            Math.max(0, x - size),
            Math.max(0, y - size),
            size * 2,
            size * 2
        );

        const blurred = this.gaussianBlur(imageData, 5);
        this.ctx.putImageData(blurred, Math.max(0, x - size), Math.max(0, y - size));
    }

    applyRect(x1, y1, x2, y2) {
        const left = Math.min(x1, x2);
        const top = Math.min(y1, y2);
        const width = Math.abs(x2 - x1);
        const height = Math.abs(y2 - y1);

        const surroundingData = this.ctx.getImageData(
            Math.max(0, left - 10),
            Math.max(0, top - 10),
            width + 20,
            height + 20
        );

        const data = surroundingData.data;
        let r = 0, g = 0, b = 0, count = 0;

        for (let i = 0; i < data.length; i += 4) {
            r += data[i];
            g += data[i + 1];
            b += data[i + 2];
            count++;
        }

        r = Math.floor(r / count);
        g = Math.floor(g / count);
        b = Math.floor(b / count);

        this.ctx.fillStyle = `rgb(${r}, ${g}, ${b})`;
        this.ctx.fillRect(left, top, width, height);

        const imageData = this.ctx.getImageData(left, top, width, height);
        const blurred = this.gaussianBlur(imageData, 3);
        this.ctx.putImageData(blurred, left, top);
    }

    gaussianBlur(imageData, radius) {
        const pixels = imageData.data;
        const width = imageData.width;
        const height = imageData.height;

        const output = new Uint8ClampedArray(pixels);

        for (let y = 0; y < height; y++) {
            for (let x = 0; x < width; x++) {
                let r = 0, g = 0, b = 0, a = 0, count = 0;

                for (let dy = -radius; dy <= radius; dy++) {
                    for (let dx = -radius; dx <= radius; dx++) {
                        const nx = x + dx;
                        const ny = y + dy;

                        if (nx >= 0 && nx < width && ny >= 0 && ny < height) {
                            const offset = (ny * width + nx) * 4;
                            r += pixels[offset];
                            g += pixels[offset + 1];
                            b += pixels[offset + 2];
                            a += pixels[offset + 3];
                            count++;
                        }
                    }
                }

                const offset = (y * width + x) * 4;
                output[offset] = r / count;
                output[offset + 1] = g / count;
                output[offset + 2] = b / count;
                output[offset + 3] = a / count;
            }
        }

        return new ImageData(output, width, height);
    }

    saveState() {
        this.history.push(this.canvas.toDataURL());
        if (this.history.length > 20) {
            this.history.shift();
        }
    }

    undo() {
        if (this.history.length > 1) {
            this.history.pop();
            const img = new Image();
            img.onload = () => {
                this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
                this.ctx.drawImage(img, 0, 0);
            };
            img.src = this.history[this.history.length - 1];
        }
    }

    clear() {
        if (this.image) {
            this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
            this.ctx.drawImage(this.image, 0, 0);
            this.history = [];
            this.saveState();
        }
    }

    download() {
        const link = document.createElement('a');
        link.download = 'removed-watermark.png';
        link.href = this.canvas.toDataURL();
        link.click();
    }
}

