    if (historyStack.length > 0) {
        const lastState = historyStack[historyStack.length - 1];
        ctx.putImageData(lastState, 0, 0);
    }
}

// 智能去水印
function removeWatermark() {
    if (!selectedArea) return;

    saveHistory();
    const { x, y, width, height } = selectedArea;
    const imageData = ctx.getImageData(x, y, width, height);
    const data = imageData.data;

    // 使用周围像素进行内容感知填充
    const borderPixels = getBorderPixels(x, y, width, height);

    for (let i = 0; i < height; i++) {
        for (let j = 0; j < width; j++) {
            const idx = (i * width + j) * 4;
            const nearestColor = getInterpolatedColor(j, i, width, height, borderPixels);
            data[idx] = nearestColor.r;
            data[idx + 1] = nearestColor.g;
            data[idx + 2] = nearestColor.b;
            data[idx + 3] = 255;
        }
    }

    ctx.putImageData(imageData, x, y);
    selectedArea = null;
}

function getBorderPixels(x, y, width, height) {
    const pixels = [];
    const borderSize = 5;

    // 上边
    for (let i = -borderSize; i < width + borderSize; i++) {
        for (let j = -borderSize; j < 0; j++) {
            const px = Math.max(0, Math.min(canvas.width - 1, x + i));
            const py = Math.max(0, Math.min(canvas.height - 1, y + j));
            const color = ctx.getImageData(px, py, 1, 1).data;
            pixels.push({ x: i, y: j, r: color[0], g: color[1], b: color[2] });
        }
    }

    // 下边
    for (let i = -borderSize; i < width + borderSize; i++) {
        for (let j = height; j < height + borderSize; j++) {
            const px = Math.max(0, Math.min(canvas.width - 1, x + i));
            const py = Math.max(0, Math.min(canvas.height - 1, y + j));
            const color = ctx.getImageData(px, py, 1, 1).data;
            pixels.push({ x: i, y: j, r: color[0], g: color[1], b: color[2] });
        }
    }

    // 左边
    for (let i = 0; i < height; i++) {
        for (let j = -borderSize; j < 0; j++) {
            const px = Math.max(0, Math.min(canvas.width - 1, x + j));
            const py = Math.max(0, Math.min(canvas.height - 1, y + i));
            const color = ctx.getImageData(px, py, 1, 1).data;
            pixels.push({ x: j, y: i, r: color[0], g: color[1], b: color[2] });
        }
    }

    // 右边
    for (let i = 0; i < height; i++) {
        for (let j = width; j < width + borderSize; j++) {
            const px = Math.max(0, Math.min(canvas.width - 1, x + j));
            const py = Math.max(0, Math.min(canvas.height - 1, y + i));
            const color = ctx.getImageData(px, py, 1, 1).data;
            pixels.push({ x: j, y: i, r: color[0], g: color[1], b: color[2] });
        }
    }

    return pixels;
}

function getInterpolatedColor(x, y, width, height, borderPixels) {
    let totalWeight = 0;
    let r = 0, g = 0, b = 0;

    borderPixels.forEach(pixel => {
        const distance = Math.sqrt(Math.pow(x - pixel.x, 2) + Math.pow(y - pixel.y, 2));
        const weight = 1 / (distance + 1);
        totalWeight += weight;
        r += pixel.r * weight;
        g += pixel.g * weight;
        b += pixel.b * weight;
    });

    return {
        r: Math.round(r / totalWeight),
        g: Math.round(g / totalWeight),
        b: Math.round(b / totalWeight)
    };
}

// 修复画笔
function applyCloneBrush(x, y) {
    const radius = brushSizeValue / 2;
    const imageData = ctx.getImageData(x - radius, y - radius, brushSizeValue, brushSizeValue);
    const data = imageData.data;

    // 获取周围像素进行模糊处理
    for (let i = 0; i < brushSizeValue; i++) {
        for (let j = 0; j < brushSizeValue; j++) {
            const dx = i - radius;
            const dy = j - radius;
            const distance = Math.sqrt(dx * dx + dy * dy);

            if (distance <= radius) {
                const idx = (i * brushSizeValue + j) * 4;
                const surroundingColor = getAverageColor(x + j - radius, y + i - radius, 3);
                const alpha = 1 - (distance / radius) * 0.5;

                data[idx] = data[idx] * (1 - alpha) + surroundingColor.r * alpha;
                data[idx + 1] = data[idx + 1] * (1 - alpha) + surroundingColor.g * alpha;
                data[idx + 2] = data[idx + 2] * (1 - alpha) + surroundingColor.b * alpha;
            }
        }
    }

    ctx.putImageData(imageData, x - radius, y - radius);
}

function getAverageColor(x, y, size) {
    let r = 0, g = 0, b = 0, count = 0;

    for (let i = -size; i <= size; i++) {
        for (let j = -size; j <= size; j++) {
            const px = Math.max(0, Math.min(canvas.width - 1, x + j));
            const py = Math.max(0, Math.min(canvas.height - 1, y + i));
            const color = ctx.getImageData(px, py, 1, 1).data;
            r += color[0];
            g += color[1];
            b += color[2];
            count++;
        }
    }

    return {
        r: Math.round(r / count),
        g: Math.round(g / count),
        b: Math.round(b / count)
    };
}

// 历史记录
function saveHistory() {
    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    historyStack.push(imageData);
    if (historyStack.length > 20) {
        historyStack.shift();
    }
}

undoBtn.addEventListener('click', () => {
    if (historyStack.length > 1) {
        historyStack.pop();
        const lastState = historyStack[historyStack.length - 1];
        ctx.putImageData(lastState, 0, 0);
    }
});

clearBtn.addEventListener('click', () => {
    selectedArea = null;
    redrawCanvas();
});

// 下载图片
downloadBtn.addEventListener('click', () => {
    const link = document.createElement('a');
    link.download = 'removed-watermark.png';
    link.href = canvas.toDataURL();
    link.click();
});
